import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";import{_ as i}from"./chunks/assets.DMkeNHu3.js";var a=JSON.parse(`{"title":"Attachment Management","description":"","frontmatter":{},"headers":[],"relativePath":"02-consumer/13-attachment.md","filePath":"02-consumer/13-attachment.md"}`),o={name:`02-consumer/13-attachment.md`};function s(n,a,o,s,c,l){return r(),t(`div`,null,[...a[0]||=[e(`<h1 id="attachment-management" tabindex="-1">Attachment Management <a class="header-anchor" href="#attachment-management" aria-label="Permalink to “Attachment Management”">​</a></h1><p><img src="`+i+`" alt="attachment.webp" width="1853" height="799"></p><p>The Attachment section is used to upload and manage files that will be displayed on the website, made available for users to download, or linked to different parts of the site, such as posts and products.</p><p>On this page, you can enter file details, specify how the file should be displayed on the site, and, if needed, assign it to a specific section of the site.</p><h2 id="_1-tips-—-page-guide" tabindex="-1">1. Tips — Page Guide <a class="header-anchor" href="#_1-tips-—-page-guide" aria-label="Permalink to “1. Tips — Page Guide”">​</a></h2><p>At the top of the sidebar, you will find tips on how to use attachments:</p><ul><li>If you do not want the file to appear in the public list of site attachments and intend to use it only by linking it to other sections, disable <strong>Is fillable</strong>.</li><li>Premium files are intended for customers to download after payment. They should not be made available to everyone like regular files.</li></ul><h2 id="_2-title-slug-and-subtitle-—-attachment-details" tabindex="-1">2. Title, Slug, and Subtitle — Attachment Details <a class="header-anchor" href="#_2-title-slug-and-subtitle-—-attachment-details" aria-label="Permalink to “2. Title, Slug, and Subtitle — Attachment Details”">​</a></h2><h3 id="title" tabindex="-1">Title <a class="header-anchor" href="#title" aria-label="Permalink to “Title”">​</a></h3><p>Enter a title for the file. This helps you identify the attachment in the admin panel and is also used in sections where the file name is displayed.</p><p>For example: <code>News manifest</code></p><h3 id="slug" tabindex="-1">Slug <a class="header-anchor" href="#slug" aria-label="Permalink to “Slug”">​</a></h3><p>This is the text identifier used to create the attachment&#39;s URL. It is usually generated from the file title.</p><p>For example: <code>news-manifest</code></p><p>Changing this value may also change the attachment&#39;s URL, so avoid changing it after publication unless necessary.</p><h3 id="subtitle" tabindex="-1">Subtitle <a class="header-anchor" href="#subtitle" aria-label="Permalink to “Subtitle”">​</a></h3><p>Enter a brief description of the file in this field. The subtitle can provide additional information about the title.</p><p>For example, if the attachment is a training file, you can enter its subject or version here.</p><h2 id="_3-description-—-attachment-description" tabindex="-1">3. Description — Attachment Description <a class="header-anchor" href="#_3-description-—-attachment-description" aria-label="Permalink to “3. Description — Attachment Description”">​</a></h2><p>Use this section to enter a more detailed description of the file. The text editor lets you format the content and use common text-editing features.</p><p>Use this section to describe the file&#39;s contents, explain its purpose, or provide instructions for downloading and using it.</p><h2 id="_4-file-—-uploading-and-downloading-the-file" tabindex="-1">4. File — Uploading and Downloading the File <a class="header-anchor" href="#_4-file-—-uploading-and-downloading-the-file" aria-label="Permalink to “4. File — Uploading and Downloading the File”">​</a></h2><p>Upload the attachment&#39;s main file in this section. After uploading, details such as the file name, extension, and size will be displayed.</p><h3 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to “Download”">​</a></h3><p>The Download button lets you download the uploaded file from the admin panel. Use it to check that the file is correct and verify its contents.</p><h3 id="short-code" tabindex="-1">Short Code <a class="header-anchor" href="#short-code" aria-label="Permalink to “Short Code”">​</a></h3><p>Once the file has been saved, a unique code labeled Short Code will be displayed; for example:</p><p><code>[ATTACHED:2]</code></p><p>You can copy this code and use it in a post or in a supported text area.</p><p>When the content is displayed on the site, the code is replaced with output appropriate to the file type:</p><ul><li><strong>Image:</strong> The image itself is displayed.</li><li><strong>Audio file:</strong> An audio player is displayed so users can play the file.</li><li><strong>Video:</strong> A video player is displayed.</li><li><strong>Other files:</strong> A download link is displayed.</li></ul><p>For example, to place an audio file within an article, simply insert its Short Code at the desired location in the content.</p><p>This lets you add a file to site content without manually entering the code needed to display an image, player, or download link.</p><h2 id="_5-is-fillable-—-display-in-the-public-list" tabindex="-1">5. Is fillable — Display in the Public List <a class="header-anchor" href="#_5-is-fillable-—-display-in-the-public-list" aria-label="Permalink to “5. Is fillable — Display in the Public List”">​</a></h2><p>This option determines whether the attachment appears in the site&#39;s public attachment list.</p><ul><li><strong>Enabled:</strong> The attachment can appear in the site&#39;s public attachment list.</li><li><strong>Disabled:</strong> The attachment is retained for use in other parts of the site without appearing in the public attachment list.</li></ul><p>For example, if you uploaded a file solely for use within an article and do not want it to appear separately in the attachment list, disable this option.</p><p>Disabling this option does not, by itself, restrict direct access to the file. This setting controls whether the file appears in the public list.</p><h2 id="_6-is-premium-—-premium-attachment" tabindex="-1">6. Is premium — Premium Attachment <a class="header-anchor" href="#_6-is-premium-—-premium-attachment" aria-label="Permalink to “6. Is premium — Premium Attachment”">​</a></h2><p>Use this option for files that require a purchase or special access to download.</p><p>For example, you can mark a training file, exclusive catalog, or downloadable document as a premium attachment intended for customers after payment.</p><ul><li><strong>Enabled:</strong> The attachment is designated as a premium file.</li><li><strong>Disabled:</strong> The attachment is treated as a regular file.</li></ul><p>Please note that enabling this option does not, by itself, manage purchases or download permissions. Actual access to the file must be controlled by the site&#39;s purchase and permission mechanisms.</p><h2 id="_7-attaching-—-linking-the-attachment-to-site-sections" tabindex="-1">7. Attaching — Linking the Attachment to Site Sections <a class="header-anchor" href="#_7-attaching-—-linking-the-attachment-to-site-sections" aria-label="Permalink to “7. Attaching — Linking the Attachment to Site Sections”">​</a></h2><p>Use this section to link a file to a specific site entity, such as a post, product, or gallery.</p><p>This is useful when you want the file to be recognized as an attachment to a specific section, rather than simply existing as a standalone file on the site.</p><h3 id="group" tabindex="-1">Group <a class="header-anchor" href="#group" aria-label="Permalink to “Group”">​</a></h3><p>This field displays the section or entity associated with the attachment. Depending on the type of link, you may need to select the destination first.</p><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to “Search”">​</a></h3><p>Use the search field to find the entity to which you want to link the file.</p><p>For example, if you want to attach a PDF to a post, search for and select the desired post.</p><p>Attachments can be linked to sections such as:</p><ul><li>Products</li><li>Posts</li><li>Groups</li><li>Categories</li><li>Clips</li><li>Galleries</li><li>Creators</li></ul><p>After selecting the destination and saving your changes, the file will be associated with the selected entity.</p><p><strong>Note:</strong> Linking a file to a post or product is different from placing its Short Code in the post&#39;s content. Linking establishes an association between the file and the entity; the Short Code inserts the file&#39;s output at a specific location in the content.</p><h2 id="_8-saving-changes" tabindex="-1">8. Saving Changes <a class="header-anchor" href="#_8-saving-changes" aria-label="Permalink to “8. Saving Changes”">​</a></h2><p>After entering the details, uploading the file, and configuring the necessary options, click Save to apply your changes.</p><p>Before saving, check that the title and description are correct, the intended file has been uploaded, and the public display, premium, and site-linking options are configured as needed.</p><h2 id="pre-save-checklist" tabindex="-1">Pre-Save Checklist <a class="header-anchor" href="#pre-save-checklist" aria-label="Permalink to “Pre-Save Checklist”">​</a></h2><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> The file title and subtitle have been entered.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> Any necessary file description has been added.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> The correct file has been uploaded.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> The Short Code is available if you need to use the file in site content.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> The public-list display setting has been configured.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> The file&#39;s premium status has been set, if needed.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-6" disabled="disabled"><label class="task-list-item-label" for="task-item-6"> The destination has been selected if the file belongs to a post, product, or other section.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-7" disabled="disabled"><label class="task-list-item-label" for="task-item-7"> The changes have been saved.</label></li></ul>`,60)]])}var c=n(o,[[`render`,s]]);export{a as __pageData,c as default};